import java.util.*;

class Solution {
    public int pairSum(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {  // slow = start of second half
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode prev = null;                        // reverse the second half
        while (slow != null) {
            ListNode nxt = slow.next;
            slow.next = prev;
            prev = slow;
            slow = nxt;
        }
        int best = 0;
        for (ListNode p = head, q = prev; q != null; p = p.next, q = q.next) {
            best = Math.max(best, p.val + q.val);    // node + its partner
        }
        return best;
    }
}
